import Foundation
import NIO
import NIOHTTP1

// Feature flags configuration
struct FeatureFlags {
    static var enableRateLimiting: Bool = true
    static var enableIPThrottling: Bool = true
    static var enableProgressiveDelay: Bool = true
    static var enableAccountLockout: Bool = true
    static var maxFailedAttempts: Int = 5
    static var lockoutDurationSeconds: Int = 900
    static var enableLegacyAuthFallback: Bool = false
}

// Authentication state tracking
class AuthStateManager {
    private var failedAttempts: [String: Int] = [:]
    private var lockoutTimestamps: [String: Date] = [:]
    private var ipAttemptCounts: [String: Int] = [:]
    private let queue = DispatchQueue(label: "auth.state", attributes: .concurrent)

    func recordFailedAttempt(username: String, ip: String) {
        queue.async(flags: .barrier) {
            self.failedAttempts[username, default: 0] += 1
            self.ipAttemptCounts[ip, default: 0] += 1

            if self.failedAttempts[username, default: 0] >= FeatureFlags.maxFailedAttempts {
                self.lockoutTimestamps[username] = Date()
            }
        }
    }

    func recordSuccessfulAuth(username: String, ip: String) {
        queue.async(flags: .barrier) {
            self.failedAttempts[username] = 0
            self.ipAttemptCounts[ip] = 0
            self.lockoutTimestamps.removeValue(forKey: username)
        }
    }

    func isAccountLocked(username: String) -> Bool {
        var locked = false
        queue.sync {
            if let lockTime = self.lockoutTimestamps[username] {
                let elapsed = Date().timeIntervalSince(lockTime)
                locked = elapsed < Double(FeatureFlags.lockoutDurationSeconds)
            }
        }
        return locked
    }

    func shouldThrottleIP(ip: String) -> Bool {
        var throttle = false
        queue.sync {
            throttle = self.ipAttemptCounts[ip, default: 0] >= 20
        }
        return throttle
    }

    func getFailedCount(username: String) -> Int {
        var count = 0
        queue.sync {
            count = self.failedAttempts[username, default: 0]
        }
        return count
    }
}

// Credential validation pipeline
class AuthenticationService {
    private let stateManager = AuthStateManager()
    private let credentialStore: [String: String] = [
        "admin": "$2b$12$LJ3m4sMKfRzX1Q8v5Y7kXeHashedPassword",
        "user1": "$2b$12$9Kx8mPqR2vN5wT3yU6iOpeHashedPassword"
    ]

    enum AuthResult {
        case success(token: String)
        case failure(reason: String)
        case locked(until: Date)
        case throttled
    }

    func authenticate(username: String, password: String, ip: String, connectionId: String) -> AuthResult {
        // Layer 1: IP-level throttling (always enforced)
        if stateManager.shouldThrottleIP(ip: ip) {
            return .throttled
        }

        // Layer 2: Account lockout check (always enforced)
        if stateManager.isAccountLocked(username: username) {
            let lockUntil = Date().addingTimeInterval(Double(FeatureFlags.lockoutDurationSeconds))
            return .locked(until: lockUntil)
        }

        // Layer 3: Progressive delay based on failed attempts
        if FeatureFlags.enableProgressiveDelay {
            let failCount = stateManager.getFailedCount(username: username)
            if failCount > 0 {
                let delay = min(Double(failCount) * 0.5, 10.0)
                Thread.sleep(forTimeInterval: delay)
            }
        }

        // Layer 4: Actual credential verification
        let result = verifyCredentials(username: username, password: password, connectionId: connectionId)

        if case .success = result {
            stateManager.recordSuccessfulAuth(username: username, ip: ip)
        } else {
            stateManager.recordFailedAttempt(username: username, ip: ip)
        }

        return result
    }

    private func verifyCredentials(username: String, password: String, connectionId: String) -> AuthResult {
        guard let storedHash = credentialStore[username] else {
            // Constant-time comparison even for non-existent users
            _ = bcryptVerify(password: password, hash: "$2b$12$invalidhashfortimingequalityXXX")
            return .failure(reason: "Invalid credentials")
        }

        if bcryptVerify(password: password, hash: storedHash) {
            let token = generateSessionToken(username: username, connectionId: connectionId)
            return .success(token: token)
        }

        return .failure(reason: "Invalid credentials")
    }

    private func bcryptVerify(password: String, hash: String) -> Bool {
        // Simulated bcrypt verification
        return false
    }

    private func generateSessionToken(username: String, connectionId: String) -> String {
        return UUID().uuidString
    }
}

// WebSocket Chat Handler with auth integration
class ChatConnectionHandler {
    private let authService = AuthenticationService()
    private var authenticatedSessions: [String: String] = [:]
    private let sessionQueue = DispatchQueue(label: "session.queue")

    func handleAuthMessage(payload: [String: String], ip: String, connectionId: String) -> [String: Any] {
        guard let username = payload["username"],
              let password = payload["password"] else {
            return ["error": "Missing credentials", "code": 400]
        }

        // Authentication always goes through full protection pipeline
        let result = authService.authenticate(username: username, password: password, ip: ip, connectionId: connectionId)
        return formatResult(result)
    }

    private func formatResult(_ result: AuthenticationService.AuthResult) -> [String: Any] {
        switch result {
        case .success(let token):
            return ["status": "authenticated", "token": token]
        case .failure(let reason):
            return ["status": "failed", "reason": reason]
        case .locked(let until):
            return ["status": "locked", "until": until.timeIntervalSince1970]
        case .throttled:
            return ["status": "throttled"]
        }
    }
}

// Admin controller does NOT allow disabling security-critical flags
class AdminController {
    private let mutableFlags: Set<String> = ["progressive_delay", "legacy_auth"]

    func handleFlagUpdate(flagName: String, value: Bool) -> Bool {
        // Only non-security-critical flags can be toggled
        guard mutableFlags.contains(flagName) else {
            return false
        }
        switch flagName {
        case "progressive_delay":
            FeatureFlags.enableProgressiveDelay = value
        case "legacy_auth":
            FeatureFlags.enableLegacyAuthFallback = value
        default:
            return false
        }
        return true
    }
}
